repo.harvests.py:
"""Harvest records."""


class Harvest:
    def __init__(self, field, kilos):
        self.field = field
        self.kilos = kilos

    def __repr__(self):
        return "Harvest(%r, %r)" % (self.field, self.kilos)


ROWS = [('hill', 46), ('lower', 58), ('upper', 23), ('upper', 22), ('hill', 26)]


def load_harvests():
    """Yield the stored harvests one at a time."""
    for field, kilos in ROWS:
        yield Harvest(field, kilos)

repo.settle.py:
"""Checking that harvests add up."""


def is_settled(harvests, expected_total):
    """Return True when the kilos of the harvests add up to expected_total. kilos may be fractional."""
    return sum(x.kilos for x in harvests) == expected_total


def shortfall(harvests, expected_total):
    """Return how much kilos is still missing, never less than 0."""
    return max(0, expected_total - sum(x.kilos for x in harvests))

