from harvests import Harvest
from settle import is_settled


def test_tenths():
    assert is_settled([Harvest("a", 0.1), Harvest("b", 0.2)], 0.3)


def test_whole_numbers():
    assert is_settled([Harvest("a", 2), Harvest("b", 3)], 5)
